import json

r1 = json.load(open('r1_table.json')); r2 = json.load(open('r2_table.json'))
r4 = json.load(open('r4_table.json')); r6 = json.load(open('r6_table.json'))
TOTAL = sum(r[-2] for r in r1); BASH = sum(r[1] for r in r1)


def c(ref, field, quote):
    return {'ref': ref, 'field': field, 'quote': quote}


def f(q, claim, kind, *cits):
    return {'q': q, 'claim': claim, 'kind': kind, 'citations': list(cits)}


